"""Ledger model, parser and aggregations."""

from __future__ import annotations

import datetime
import re
from dataclasses import dataclass
from decimal import Decimal
from typing import Dict, Iterable, List, Optional

_DATE_RE = re.compile(r"[0-9]{4}-[0-9]{2}-[0-9]{2}")
_AMOUNT_RE = re.compile(r"[+-]?[0-9]+(\.[0-9]{1,2})?")
_SEPARATOR_RE = re.compile(r"[ \t]+")
_LINE_END_RE = re.compile(r"\r\n|\n|\r")


class ParseError(ValueError):
    """A line of the ledger is malformed. ``line`` is its 1-based number."""

    def __init__(self, line: int, reason: str) -> None:
        super().__init__("line %d: %s" % (line, reason))
        self.line = line
        self.reason = reason


@dataclass(frozen=True)
class Entry:
    date: datetime.date
    category: str
    amount: Decimal
    note: str = ""


def parse_date(text: str) -> datetime.date:
    """Parse ``YYYY-MM-DD``; raise ValueError if malformed or nonexistent."""
    if not _DATE_RE.fullmatch(text):
        raise ValueError("invalid date %r (expected YYYY-MM-DD)" % text)
    try:
        return datetime.date(int(text[:4]), int(text[5:7]), int(text[8:10]))
    except ValueError:
        raise ValueError("invalid date %r (no such day)" % text) from None


def _parse_line(line: str, number: int) -> Entry:
    parts = _SEPARATOR_RE.split(line.strip(), 3)
    if len(parts) < 3:
        raise ParseError(
            number, "expected date, category and amount, got %r" % line.strip()
        )
    date_text, category, amount_text = parts[0], parts[1], parts[2]
    note = parts[3].strip() if len(parts) > 3 else ""
    try:
        date = parse_date(date_text)
    except ValueError as exc:
        raise ParseError(number, str(exc)) from None
    if not _AMOUNT_RE.fullmatch(amount_text):
        raise ParseError(number, "invalid amount %r" % amount_text)
    return Entry(date, category.lower(), Decimal(amount_text), note)


def parse(text: str) -> List[Entry]:
    """Parse ledger text into entries, in file order."""
    entries = []
    for number, line in enumerate(_LINE_END_RE.split(text), start=1):
        stripped = line.strip()
        if not stripped or stripped.startswith("#"):
            continue
        entries.append(_parse_line(line, number))
    return entries


def balance(entries: Iterable[Entry]) -> Decimal:
    total = Decimal("0")
    for entry in entries:
        total += entry.amount
    return total


def by_category(entries: Iterable[Entry]) -> Dict[str, Decimal]:
    totals: Dict[str, Decimal] = {}
    for entry in entries:
        totals[entry.category] = totals.get(entry.category, Decimal("0")) + entry.amount
    return totals


def by_month(entries: Iterable[Entry]) -> Dict[str, Decimal]:
    totals: Dict[str, Decimal] = {}
    for entry in entries:
        key = "%04d-%02d" % (entry.date.year, entry.date.month)
        totals[key] = totals.get(key, Decimal("0")) + entry.amount
    return totals


def filter_entries(
    entries: Iterable[Entry],
    category: Optional[str] = None,
    since: Optional[datetime.date] = None,
    until: Optional[datetime.date] = None,
) -> List[Entry]:
    wanted = category.lower() if category is not None else None
    result = []
    for entry in entries:
        if wanted is not None and entry.category != wanted:
            continue
        if since is not None and entry.date < since:
            continue
        if until is not None and entry.date > until:
            continue
        result.append(entry)
    return result
"""Command line interface: ``pennywise`` / ``python -m pennywise``."""

from __future__ import annotations

import argparse
import csv
import datetime
import io
import json
import sys
from decimal import Decimal
from typing import Dict, List, Optional, Sequence

from .ledger import (
    Entry,
    ParseError,
    balance,
    by_category,
    by_month,
    filter_entries,
    parse,
    parse_date,
)

PROG = "pennywise"


class _ReadError(Exception):
    """The ledger file could not be read."""


def format_amount(amount: Decimal) -> str:
    """Two decimals; sign only for negatives, never ``-0.00``."""
    if amount == 0:
        return "0.00"
    return format(amount, ".2f")


def format_entry(entry: Entry) -> str:
    line = "%s %s %s" % (entry.date.isoformat(), entry.category, format_amount(entry.amount))
    if entry.note:
        line += " " + entry.note
    return line


def _date_arg(text: str) -> datetime.date:
    try:
        return parse_date(text)
    except ValueError as exc:
        raise argparse.ArgumentTypeError(str(exc)) from None


def _build_parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(
        prog=PROG, description="Read a plain-text household ledger and report where the money went."
    )
    sub = parser.add_subparsers(dest="command", metavar="COMMAND")
    sub.required = True

    p = sub.add_parser("balance", help="print the total of all entries")
    p.add_argument("file", metavar="FILE", help="ledger file, or - for standard input")
    p.add_argument("--json", action="store_true", help="print JSON")

    p = sub.add_parser("summary", help="print totals per category or month")
    p.add_argument("file", metavar="FILE", help="ledger file, or - for standard input")
    p.add_argument("--by", choices=["category", "month"], default="category")
    p.add_argument("--json", action="store_true", help="print JSON")

    p = sub.add_parser("list", help="print matching entries, oldest first")
    p.add_argument("file", metavar="FILE", help="ledger file, or - for standard input")
    p.add_argument("--category", help="only this category (case-insensitive)")
    p.add_argument("--since", type=_date_arg, metavar="DATE", help="from this date (inclusive)")
    p.add_argument("--until", type=_date_arg, metavar="DATE", help="up to this date (inclusive)")
    p.add_argument("--json", action="store_true", help="print JSON")

    p = sub.add_parser("add", help="append an entry to FILE")
    p.add_argument("file", metavar="FILE", help="ledger file (created if missing)")
    p.add_argument("date", metavar="DATE")
    p.add_argument("category", metavar="CATEGORY")
    p.add_argument("amount", metavar="AMOUNT")
    p.add_argument("note", metavar="NOTE", nargs="?", default="")

    p = sub.add_parser("export", help="print entries as CSV")
    p.add_argument("file", metavar="FILE", help="ledger file, or - for standard input")
    p.add_argument("--format", choices=["csv"], default="csv")
    return parser


def _read_text(path: str) -> str:
    try:
        if path == "-":
            text = sys.stdin.read()
            return text[1:] if text.startswith("﻿") else text
        with open(path, "r", encoding="utf-8-sig", newline="") as handle:
            return handle.read()
    except (OSError, UnicodeDecodeError) as exc:
        name = "<stdin>" if path == "-" else path
        reason = exc.strerror if isinstance(exc, OSError) and exc.strerror else str(exc)
        raise _ReadError("cannot read %s: %s" % (name, reason)) from None


def _sorted_entries(entries: List[Entry]) -> List[Entry]:
    return sorted(entries, key=lambda e: e.date)  # stable


def _totals(mapping: Dict[str, Decimal]) -> Dict[str, str]:
    return {name: format_amount(mapping[name]) for name in sorted(mapping)}


def _cmd_balance(args: argparse.Namespace, entries: List[Entry]) -> str:
    total = format_amount(balance(entries))
    if args.json:
        return json.dumps({"balance": total}) + "\n"
    return total + "\n"


def _cmd_summary(args: argparse.Namespace, entries: List[Entry]) -> str:
    grouped = by_category(entries) if args.by == "category" else by_month(entries)
    totals = _totals(grouped)
    if args.json:
        return json.dumps(totals) + "\n"
    return "".join("%s  %s\n" % (name, total) for name, total in totals.items())


def _cmd_list(args: argparse.Namespace, entries: List[Entry]) -> str:
    chosen = _sorted_entries(filter_entries(entries, args.category, args.since, args.until))
    if args.json:
        return json.dumps(
            [
                {
                    "date": e.date.isoformat(),
                    "category": e.category,
                    "amount": format_amount(e.amount),
                    "note": e.note,
                }
                for e in chosen
            ]
        ) + "\n"
    return "".join(format_entry(e) + "\n" for e in chosen)


def _cmd_export(args: argparse.Namespace, entries: List[Entry]) -> str:
    out = io.StringIO()
    writer = csv.writer(out, lineterminator="\n")
    writer.writerow(["date", "category", "amount", "note"])
    for e in _sorted_entries(entries):
        writer.writerow([e.date.isoformat(), e.category, format_amount(e.amount), e.note])
    return out.getvalue()


_READERS = {
    "balance": _cmd_balance,
    "summary": _cmd_summary,
    "list": _cmd_list,
    "export": _cmd_export,
}


def _error(message: str) -> None:
    sys.stderr.write("%s: %s\n" % (PROG, message))


def _build_line(args: argparse.Namespace) -> str:
    """Validate the arguments of ``add``; return the canonical ledger line."""
    for label, value in (("date", args.date), ("category", args.category), ("amount", args.amount)):
        if not value or any(ch.isspace() for ch in value):
            raise ParseError(1, "invalid %s %r" % (label, value))
    if "\n" in args.note or "\r" in args.note:
        raise ParseError(1, "note must not contain a newline")
    parsed = parse("%s %s %s %s" % (args.date, args.category, args.amount, args.note))
    return format_entry(parsed[0])


def _cmd_add(args: argparse.Namespace) -> str:
    line = _build_line(args)
    try:
        try:
            with open(args.file, "rb") as handle:
                handle.seek(0, io.SEEK_END)
                needs_newline = False
                if handle.tell() > 0:
                    handle.seek(-1, io.SEEK_END)
                    needs_newline = handle.read(1) != b"\n"
        except FileNotFoundError:
            needs_newline = False
        data = (b"\n" if needs_newline else b"") + line.encode("utf-8") + b"\n"
        with open(args.file, "ab") as handle:
            handle.write(data)
    except OSError as exc:
        raise _ReadError("cannot write %s: %s" % (args.file, exc.strerror or exc)) from None
    return line + "\n"


def main(argv: Optional[Sequence[str]] = None) -> int:
    parser = _build_parser()
    try:
        args = parser.parse_args(argv)
    except SystemExit as exc:
        code = exc.code
        return code if isinstance(code, int) else (0 if code is None else 2)
    try:
        if args.command == "add":
            output = _cmd_add(args)
        else:
            text = _read_text(args.file)
            name = "<stdin>" if args.file == "-" else args.file
            entries = parse(text)
            output = _READERS[args.command](args, entries)
    except ParseError as exc:
        _error(str(exc) if args.command == "add" else "%s: %s" % (name, exc))
        return 1
    except _ReadError as exc:
        _error(str(exc))
        return 2
    sys.stdout.write(output)
    return 0


if __name__ == "__main__":
    sys.exit(main())
